// Dados do agendamento recem criado
const apptResponse = $('Criar agendamento').item.json;

// Se o agendamento falhou, pula PIX
if (!apptResponse.ok || !apptResponse.appointment_id) {
  return [{ json: { skip_pix: true, reason: 'Agendamento sem appointment_id' } }];
}

// Dados do contexto (buscado pelo node 'Buscar contexto' mais cedo no workflow)
const ctx = $('Buscar contexto').item.json;
const services = ctx.services || [];

// Busca o primeiro servico com preco positivo
const service = services.find(function(s) { return s.price && Number(s.price) > 0; });
const priceRaw = service ? Number(service.price) : 0;

if (!priceRaw) {
  return [{ json: { skip_pix: true, reason: 'Sem servico com preco configurado' } }];
}

// Sinal de 10% do valor integral, minimo R$50
const depositAmount = Math.max(50, Math.round(priceRaw * 0.10 * 100) / 100);

return [{
  json: {
    skip_pix: false,
    appointment_id: apptResponse.appointment_id,
    nutritionist_id: ctx.nutritionist ? ctx.nutritionist.id : null,
    client_phone: ctx.client ? ctx.client.phone : null,
    client_name: (ctx.client && ctx.client.name) ? ctx.client.name : 'Cliente',
    amount: depositAmount,
    type: 'sinal',
  }
}];
